/// Parse rg's default text output. Match lines are `path:line:text`; context
/// lines (with -C) are `path-N:text` between `--` block separators.
fn parse_matches(stdout: &str) -> Vec<Value> {
    let mut matches: Vec<Value> = Vec::new();
    for block in stdout.split("--\n") {
        // (path, line_no, text, is_match)
        let mut lines: Vec<(String, Option<u64>, String, bool)> = Vec::new();
        for line in block.lines() {
            if line.is_empty() {
                continue;
            }
            if let Some((path, line_no, text)) = parse_match_line(line) {
                lines.push((path, line_no, text.to_string(), true));
            } else if let Some((path, line_no, text)) = parse_context_line(line) {
                lines.push((path, line_no, text.to_string(), false));
            }
        }
        // Attach context to each match in the block.
        for (i, (path, line_no, text, is_match)) in lines.iter().enumerate() {
            if !is_match {
                continue;
            }
            let before = lines[..i]
                .iter()
                .rev()
                .take_while(|(_, _, _, m)| !m)
                .map(|(_, _, t, _)| t.clone())
                .collect::<Vec<_>>()
                .into_iter()
                .rev()
                .collect::<Vec<_>>();
            let after = lines[i + 1..]
                .iter()
                .take_while(|(_, _, _, m)| !m)
                .map(|(_, _, t, _)| t.clone())
                .collect::<Vec<_>>();
            let mut m = json!({
                "path": path,
                "line": line_no,
                "text": text,
            });
            if !before.is_empty() {
                m["context_before"] = json!(before);
            }
            if !after.is_empty() {
                m["context_after"] = json!(after);
            }
            matches.push(m);
        }
    }
    matches
}

/// "path:line:text" -> (path, Some(line), text). Splits on the first two colons.
fn parse_match_line(line: &str) -> Option<(String, Option<u64>, &str)> {
    let mut parts = line.splitn(3, ':');
    let path = parts.next()?.to_string();
    let line_no = parts.next()?.parse::<u64>().ok()?;
    let text = parts.next().unwrap_or("");
    Some((path, Some(line_no), text))
}

/// "path-N:text" (context line) -> (path, None, text).
fn parse_context_line(line: &str) -> Option<(String, Option<u64>, &str)> {
    let idx = line.rfind(':')?;
    let path_part = &line[..idx];
    if path_part.ends_with('-') {
        Some((
            path_part[..path_part.len() - 1].to_string(),
            None,
            &line[idx + 1..],
        ))
    } else {
        None
    }
}